add_action( 'init', 'perfectpixel_shop_atc_form_setup' );
add_action( 'wp_enqueue_scripts', 'perfectpixel_shop_atc_form_scripts' );

function perfectpixel_shop_atc_form_setup() {
	remove_action( 'woocommerce_after_shop_loop_item', 'woocommerce_template_loop_add_to_cart', 10 );
	add_action( 'woocommerce_after_shop_loop_item', 'perfectpixel_shop_atc_form', 10 );
}

function perfectpixel_shop_atc_form() {
	global $product;
	if ( ! $product ) {
		return;
	}
	if ( $product->is_purchasable() && $product->is_in_stock() ) {
		woocommerce_template_single_add_to_cart();
	} else {
		woocommerce_template_loop_add_to_cart(); // "Read more" etc.
	}
}

function perfectpixel_shop_atc_form_scripts() {
	if ( function_exists( 'is_shop' ) && ( is_shop() || is_product_taxonomy() ) ) {
		wp_enqueue_script( 'wc-add-to-cart-variation' );
	}
}
